%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% H2 State Feedback Controller Design using LMI Formulation
% 
% This MATLAB code designs an H2 state feedback controller that minimizes
% the sum of squared H2 norms of transfer functions from input disturbance
% to output and to control input.
%
% The optimization problem is formulated using the Schur complement lemma
% and bounded real lemma to handle the nonlinearity in the system structure.
%
% System: Active Suspension System
% Objective: Minimize ||T_wz||_2^2 + ||T_wu||_2^2
% Where: T_wz = transfer from disturbance to output (Cx)
%        T_wu = transfer from disturbance to control input (-Kx)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

clc
clear all
close all

%% Load and prepare system data
% Load system identification data
load('data3.mat');

% Identify system using Box-Jenkins model
G3 = bj(data3, [5, 5, 5, 5, 1]);

% Convert discrete-time model to continuous-time
G3_c = d2c(G3);

% Extract state-space matrices
[A, B, C, D] = ssdata(G3_c);

% System dimensions
n = size(A, 1);  % Number of states
m = size(B, 2);  % Number of inputs
p = size(C, 1);  % Number of outputs

%% H2 State Feedback Controller Design using LMI Formulation
% Define decision variables for YALMIP
X = sdpvar(n, n, 'symmetric');  % Lyapunov matrix
Y = sdpvar(m, n, 'full');       % Y = K*X
Z = sdpvar(p, p, 'symmetric');  % Auxiliary variable for trace minimization

% Define epsilon for strict inequalities (numerical robustness)
epsilon = 1e-6;

% LMI 1: Stability condition (Bounded Real Lemma formulation)
% A*X + X*A' - B*Y - Y'*B' + B*B' <= -epsilon*I
LMI1 = [A*X + X*A' - B*Y - Y'*B' + B*B' <= -epsilon*eye(n)];

% LMI 2: Positive definiteness of X
% X >= epsilon*I
LMI2 = [X >= epsilon*eye(n)];

% LMI 3: Schur complement for trace minimization
% [Z, C*X; X*C', X] >= 0
% This ensures trace(Z) >= trace(C*X*C')
LMI3 = [[Z, C*X; X*C', X] >= 0];

% Combine all LMIs
LMIs = [LMI1, LMI2, LMI3];

% Objective function: Minimize trace(Z)
% This minimizes an upper bound on the H2 norm squared
Objective = trace(Z);

% Solver settings
options = sdpsettings('solver', 'sedumi', 'verbose', 1, 'saveduals', 0);

% Solve the LMI optimization problem
diagnostics = optimize(LMIs, Objective, options);

% Check if solution was found
if diagnostics.problem == 0
    disp('Optimization successfully solved!');
else
    error(['Optimization failed: ', diagnostics.info]);
end

%% Extract solution and compute controller gain
% Get optimal values
X_opt = value(X);
Y_opt = value(Y);
Z_opt = value(Z);

% Compute controller gain: K = Y * X^(-1)
K = Y_opt / X_opt;

% Compute achieved H2 norm
% Solve Lyapunov equation for closed-loop system
A_cl = A - B*K;

% Check stability of closed-loop system
eig_cl = eig(A_cl);
if any(real(eig_cl) >= 0)
    warning('Closed-loop system may be unstable!');
    disp('Closed-loop eigenvalues:');
    disp(eig_cl);
end

% Compute H2 norm using Lyapunov equation solution
% Solve: A_cl*P + P*A_cl' + B*B' = 0
P = lyap(A_cl, B*B');
h2_norm_squared = trace(C*P*C');
h2_norm = sqrt(h2_norm_squared);

%% Display results
fprintf('\n=== H2 State Feedback Controller Design Results ===\n');
fprintf('Controller gain K:\n');
disp(K);
fprintf('Achieved H2 norm: %.4f\n', h2_norm);
fprintf('Trace(Z) (upper bound): %.4f\n', trace(Z_opt));
fprintf('Trace(C*X*C''') (actual): %.4f\n', trace(C*X_opt*C'));

%% Analyze closed-loop system
% Create closed-loop system
sys_cl = ss(A_cl, B, C, D);

% Step response
figure('Name', 'Step Response - H2 Controller');
step(sys_cl);
grid on;
title('Step Response of Closed-Loop System with H2 Controller');

% Bode plot
figure('Name', 'Bode Plot - H2 Controller');
bode(sys_cl);
grid on;
title('Bode Plot of Closed-Loop System with H2 Controller');

% Pole-zero map
figure('Name', 'Pole-Zero Map - H2 Controller');
pzmap(sys_cl);
grid on;
title('Pole-Zero Map of Closed-Loop System with H2 Controller');

%% Compare with LQR design
% LQR design for comparison
Q_lqr = C'*C + 1e-3*eye(n);  % State weighting
R_lqr = eye(m);              % Control weighting

[K_lqr, P_lqr, eig_lqr] = lqr(A, B, Q_lqr, R_lqr);

% Create LQR closed-loop system
A_cl_lqr = A - B*K_lqr;
sys_cl_lqr = ss(A_cl_lqr, B, C, D);

% Compute H2 norm for LQR
P_lqr_cl = lyap(A_cl_lqr, B*B');
h2_norm_lqr_squared = trace(C*P_lqr_cl*C');
h2_norm_lqr = sqrt(h2_norm_lqr_squared);

% Step response comparison
figure('Name', 'Step Response Comparison');
step(sys_cl, 'b-', sys_cl_lqr, 'r--');
grid on;
legend('H2 Controller', 'LQR Controller', 'Location', 'best');
title('Step Response Comparison: H2 vs LQR');

% Display comparison results
fprintf('\n=== Comparison with LQR ===\n');
fprintf('LQR controller gain:\n');
disp(K_lqr);
fprintf('H2 norm - H2 Controller: %.4f\n', h2_norm);
fprintf('H2 norm - LQR: %.4f\n', h2_norm_lqr);
fprintf('Improvement: %.2f%%\n', 100*(h2_norm_lqr - h2_norm)/h2_norm_lqr);

%% Performance metrics table
fprintf('\n=== Performance Metrics ===\n');
fprintf('%-25s %-15s %-15s\n', 'Metric', 'H2 Controller', 'LQR');
fprintf('%-25s %-15.4f %-15.4f\n', 'H2 Norm', h2_norm, h2_norm_lqr);
fprintf('%-25s %-15.4f %-15.4f\n', 'Control Effort (||K||_F)', norm(K, 'fro'), norm(K_lqr, 'fro'));

% Compute stability margins
[GM_h2, PM_h2, Wcg_h2, Wcp_h2] = margin(sys_cl);
[GM_lqr, PM_lqr, Wcg_lqr, Wcp_lqr] = margin(sys_cl_lqr);

fprintf('%-25s %-15.2f %-15.2f\n', 'Gain Margin (dB)', 20*log10(GM_h2), 20*log10(GM_lqr));
fprintf('%-25s %-15.2f %-15.2f\n', 'Phase Margin (deg)', PM_h2, PM_lqr);

%% Additional analysis: Frequency response comparison
w = logspace(-1, 3, 1000);  % Frequency range

% Compute frequency responses
[mag_h2, phase_h2, w_h2] = bode(sys_cl, w);
[mag_lqr, phase_lqr, w_lqr] = bode(sys_cl_lqr, w);

% Convert to dB
mag_h2_db = 20*log10(squeeze(mag_h2));
mag_lqr_db = 20*log10(squeeze(mag_lqr));

% Plot frequency response comparison
figure('Name', 'Frequency Response Comparison');
subplot(2,1,1);
semilogx(w, mag_h2_db, 'b-', 'LineWidth', 1.5);
hold on;
semilogx(w, mag_lqr_db, 'r--', 'LineWidth', 1.5);
grid on;
xlabel('Frequency (rad/s)');
ylabel('Magnitude (dB)');
title('Frequency Response Comparison');
legend('H2 Controller', 'LQR Controller', 'Location', 'best');

subplot(2,1,2);
semilogx(w, squeeze(phase_h2), 'b-', 'LineWidth', 1.5);
hold on;
semilogx(w, squeeze(phase_lqr), 'r--', 'LineWidth', 1.5);
grid on;
xlabel('Frequency (rad/s)');
ylabel('Phase (deg)');
legend('H2 Controller', 'LQR Controller', 'Location', 'best');

%% Save results
save('h2_controller_results.mat', 'K', 'X_opt', 'h2_norm', 'K_lqr', 'h2_norm_lqr', ...
     'sys_cl', 'sys_cl_lqr', 'A', 'B', 'C', 'D');

fprintf('\nResults saved to ''h2_controller_results.mat''\n');
