    public static int lat(int[] sbox, int a, int b) {
        int count = 0;

        for(int x = 0; x < 8; x++) {
            // Get binary representation of input x
            int x0 = (x >> 2) & 1;
            int x1 = (x >> 1) & 1;
            int x2 = x & 1;

            // Get S-box output for input x
            int fx = sbox[x];
            int fx0 = (fx >> 2) & 1;
            int fx1 = (fx >> 1) & 1;
            int fx2 = fx & 1;

            // Get binary representation of mask a
            int a0 = (a >> 2) & 1;
            int a1 = (a >> 1) & 1;
            int a2 = a & 1;

            // Get binary representation of mask b
            int b0 = (b >> 2) & 1;
            int b1 = (b >> 1) & 1;
            int b2 = b & 1;

            // Compute a·x = a0*x0 ⊕ a1*x1 ⊕ a2*x2
            int a_dot_x = (a0 & x0) ^ (a1 & x1) ^ (a2 & x2);

            // Compute b·S(x) = b0*fx0 ⊕ b1*fx1 ⊕ b2*fx2
            int b_dot_fx = (b0 & fx0) ^ (b1 & fx1) ^ (b2 & fx2);

            if(a_dot_x == b_dot_fx) {
                count++;
            }
        }

        return count;
    }
