import java.text.DecimalFormat;
import java.util.Random;
import java.util.Scanner;

public class DiceSumSimulator {
    public static void main(String[] args) {
        // Theoretical probabilities array for sums 2-12
        // Each index represents a possible sum, with 0 and 1 unused
        double[] theoreticalProbs = new double[13];
        theoreticalProbs[2] = 1.0 / 36.0;  // Only 1+1
        theoreticalProbs[3] = 2.0 / 36.0;  // 1+2, 2+1
        theoreticalProbs[4] = 3.0 / 36.0;  // 1+3, 2+2, 3+1
        theoreticalProbs[5] = 4.0 / 36.0;  // 1+4, 2+3, 3+2, 4+1
        theoreticalProbs[6] = 5.0 / 36.0;  // 1+5, 2+4, 3+3, 4+2, 5+1
        theoreticalProbs[7] = 6.0 / 36.0;  // All combinations with sum 7
        theoreticalProbs[8] = 5.0 / 36.0;  // 2+6, 3+5, 4+4, 5+3, 6+2
        theoreticalProbs[9] = 4.0 / 36.0;  // 3+6, 4+5, 5+4, 6+3
        theoreticalProbs[10] = 3.0 / 36.0; // 4+6, 5+5, 6+4
        theoreticalProbs[11] = 2.0 / 36.0; // 5+6, 6+5
        theoreticalProbs[12] = 1.0 / 36.0; // Only 6+6

        Random rand = new Random();
        DecimalFormat df = new DecimalFormat("#.####");
        Scanner scanner = new Scanner(System.in);

        // Print theoretical probabilities
        System.out.println("=".repeat(80));
        System.out.println("DICE SUM PROBABILITY SIMULATOR");
        System.out.println("=".repeat(80));
        System.out.println("\nTheoretical Probabilities:");
        System.out.println("-".repeat(40));
        System.out.println("Sum\tP(X)\t\tPercentage");
        System.out.println("-".repeat(40));
        for (int sum = 2; sum <= 12; sum++) {
            System.out.println(sum + "\t" + df.format(theoreticalProbs[sum]) 
                + "\t\t" + df.format(theoreticalProbs[sum] * 100) + "%");
        }

        // Get user input for simulation sizes
        System.out.println("\nEnter the number of rolls for each simulation (comma-separated).");
        System.out.println("Example: 36, 500, 10000");
        int[] rollCounts;
        while (true) {
            try {
                System.out.print("\nEnter roll counts: ");
                String input = scanner.nextLine();
                String[] parts = input.split(",");
                rollCounts = new int[parts.length];

                for (int i = 0; i < parts.length; i++) {
                    rollCounts[i] = Integer.parseInt(parts[i].trim());
                    if (rollCounts[i] <= 0) {
                        throw new IllegalArgumentException("All roll counts must be positive");
                    }
                }
                break;
            } catch (Exception e) {
                System.out.println("Invalid input. Please enter comma-separated positive integers.");
            }
        }

        // Run simulations
        for (int numRolls : rollCounts) {
            // Array to store counts for each sum (2-12)
            int[] counts = new int[13];

            // Simulate dice rolls
            for (int i = 0; i < numRolls; i++) {
                int die1 = rand.nextInt(6) + 1; // Random number 1-6
                int die2 = rand.nextInt(6) + 1; // Random number 1-6
                int sum = die1 + die2;
                counts[sum]++; // Increment count for this sum
            }

            // Calculate empirical probabilities
            double[] empiricalProbs = new double[13];
            for (int sum = 2; sum <= 12; sum++) {
                empiricalProbs[sum] = (double) counts[sum] / numRolls;
            }

            // Print simulation results
            System.out.println("\n" + "=".repeat(80));
            System.out.println("SIMULATION: " + numRolls + " rolls");
            System.out.println("=".repeat(80));
            System.out.println("Sum\tCount\tEmp Prob\tTheoretical\tDifference");
            System.out.println("-".repeat(80));

            for (int sum = 2; sum <= 12; sum++) {
                String countStr = Integer.toString(counts[sum]);
                String empProbStr = df.format(empiricalProbs[sum]);
                String theoProbStr = df.format(theoreticalProbs[sum]);
                double diff = empiricalProbs[sum] - theoreticalProbs[sum];
                String diffStr = df.format(diff);

                // Adjust tabs based on count length for consistent formatting
                String countTabs;
                if (counts[sum] >= 1000) {
                    countTabs = "\t";
                } else if (counts[sum] >= 100) {
                    countTabs = "\t";
                } else {
                    countTabs = "\t\t";
                }

                System.out.println(sum + "\t" + countStr + countTabs + 
                                 empProbStr + "\t\t" + theoProbStr + "\t\t" + diffStr);
            }
        }

        // Answer specific questions
        System.out.println("\n" + "=".repeat(80));
        System.out.println("ANSWERS TO SPECIFIC QUESTIONS:");
        System.out.println("=".repeat(80));
        System.out.println("1. Total number of possible outcomes: " + (6 * 6) + " = 36");
        System.out.println("2. P(X = 2) = " + df.format(theoreticalProbs[2]));
        System.out.println("3. P(X = 3) = " + df.format(theoreticalProbs[3]));
        System.out.println("4. P(X = 4) = " + df.format(theoreticalProbs[4]));
        System.out.println("5. P(X = 5) = " + df.format(theoreticalProbs[5]));
        System.out.println("6. P(X = 6) = " + df.format(theoreticalProbs[6]));
        System.out.println("7. P(X = 7) = " + df.format(theoreticalProbs[7]));
        System.out.println("8. P(X = 8) = " + df.format(theoreticalProbs[8]));
        System.out.println("9. P(X = 9) = " + df.format(theoreticalProbs[9]));
        System.out.println("10. P(X = 10) = " + df.format(theoreticalProbs[10]));
        System.out.println("11. P(X = 11) = " + df.format(theoreticalProbs[11]));
        System.out.println("12. P(X = 12) = " + df.format(theoreticalProbs[12]));
        System.out.println("\nWith infinite rolls, we would expect " + 
                         df.format(theoreticalProbs[7] * 100) + "% of rolls to have a sum of 7.");

        scanner.close();
    }
}
