void RatingManager::updateRating(const std::string& playerName, bool won) {
    std::lock_guard<std::mutex> lock(ratingsMutex);

    if (ratings.find(playerName) == ratings.end()) {
        ratings[playerName] = PlayerStats{};
    }

    auto& stats = ratings[playerName];
    stats.gamesPlayed++;

    if (won) {
        stats.wins++;
    } else {
        stats.losses++;
    }

    stats.winRate = static_cast<double>(stats.wins) / stats.gamesPlayed;
    saveRatings();
}
