function main()
    fprintf('========================================\n');
    fprintf('    2-D SOURCE PANEL METHOD\n');
    fprintf('========================================\n\n');

    % Get airfoil geometry
    fprintf('AIRFOIL GEOMETRY INPUT:\n');
    fprintf('1. Use default NACA 0012 airfoil\n');
    fprintf('2. Load from text file\n');

    choice = input('Enter choice (1 or 2): ', 's');

    if strcmp(choice, '2')
        filename = input('Enter filename: ', 's');
        if ~exist(filename, 'file')
            fprintf('File not found. Using default airfoil.\n');
            [x_points, y_points] = create_default_airfoil();
        else
            [x_points, y_points] = load_airfoil_points(filename);
        end
    else
        [x_points, y_points] = create_default_airfoil();
    end

    % Get flow conditions
    fprintf('\n=== FLOW CONDITIONS ===\n');
    V_inf = input('Enter free stream velocity (m/s): ');
    alpha_deg = input('Enter angle of attack (degrees): ');
    alpha_rad = deg2rad(alpha_deg);

    % Panel numbers for convergence study
    panel_numbers = [10, 20, 40, 80, 160];
    Cl_values = zeros(size(panel_numbers));

    fprintf('\n=== CONVERGENCE STUDY ===\n');
    fprintf('Panel # |   Cl   | Error (%%)\n');
    fprintf('-----------------------------\n');

    for i = 1:length(panel_numbers)
        n_panels = panel_numbers(i);
        panels = create_panels(x_points, y_points, n_panels);
        [source_strengths, gamma] = solve_flow(panels, V_inf, alpha_rad);

        % Compute lift coefficient
        chord = max(x_points) - min(x_points);
        Cl = 2 * gamma / (V_inf * chord);
        Cl_values(i) = Cl;

        % Display results
        if i > 1
            error = abs((Cl - Cl_values(i-1)) / Cl_values(i-1)) * 100;
            fprintf('%7d | %6.4f | %7.2f\n', n_panels, Cl, error);
        else
            fprintf('%7d | %6.4f |     -\n', n_panels, Cl);
        end
    end

    % Final calculation with finest mesh
    panels = create_panels(x_points, y_points, 160);
    [source_strengths, gamma] = solve_flow(panels, V_inf, alpha_rad);
    Cp = compute_pressure_coefficient(panels, source_strengths, gamma, V_inf, alpha_rad);

    % Compute lift coefficient
    Cl = 2 * gamma / (V_inf * chord);

    % Analytical comparison (thin airfoil theory)
    Cl_theory = 2 * pi * alpha_rad;
    theta = linspace(0, pi, length(panels));
    x_theory = 0.5 * (1 - cos(theta));
    Cp_theory = 1 - 4 * sin(theta).^2 .* (sin(alpha_rad)./sin(theta) + cos(alpha_rad)).^2;

    % Display final results
    fprintf('\n=== FINAL RESULTS ===\n');
    fprintf('Lift Coefficient (Cl): %.6f\n', Cl);
    fprintf('Theoretical Cl (thin airfoil): %.6f\n', Cl_theory);
    fprintf('Percentage difference: %.2f%%\n', abs(Cl - Cl_theory)/Cl_theory*100);

    % Plot results with comparison
    plot_results(panels, x_points, y_points, Cp, V_inf, alpha_deg, Cp_theory, x_theory);
