/**
 * @brief Enhanced Izhikevich Neuron with Biological Explanations
 * 
 * This C++ implementation models neurons in primitive animal nervous systems with:
 * - Biologically plausible Izhikevich dynamics
 * - STDP-based synaptic plasticity
 * - Dynamic connection management
 * - Robust error handling
 */
class IzhikevichNeuron {
private:
    // Neuron identification
    const size_t id_;

    // Izhikevich parameters - biologically realistic ranges
    double a_;  // Time scale of recovery (0.02-0.1 typical)
    double b_;  // Sensitivity to membrane potential (0.2 typical)
    double c_;  // Post-spike reset potential (-65 mV typical)
    double d_;  // Post-spike recovery reset (2-8 typical)

    // State variables
    double v_;  // Membrane potential (-70mV resting typical)
    double u_;  // Recovery variable

    // Spike tracking
    bool has_spiked_;
    double last_spike_time_;

    // Connectivity
    std::unordered_map<size_t, double> input_weights_;
    std::unordered_map<size_t, double> output_weights_;

    // STDP parameters
    double stdp_learning_rate_ = 0.01;
    double stdp_tau_plus_ = 20.0;  // LTP time constant
    double stdp_tau_minus_ = 20.0; // LTD time constant

public:
    IzhikevichNeuron(size_t id, double a, double b, double c, double d) 
        : id_(id), a_(a), b_(b), c_(c), d_(d), v_(-70.0), u_(b * -70.0), 
          has_spiked_(false), last_spike_time_(-1000.0) 
    {
        // Biological parameter validation
        if(a <= 0 || b <= 0) {
            throw std::invalid_argument("Izhikevich parameters must be positive");
        }
    }

    // Connection management with error checking
    bool connect_to(size_t target_id, double weight) {
        if(target_id == id_) throw std::invalid_argument("No self-connections allowed");
        if(weight <= 0) throw std::invalid_argument("Weight must be positive");

        return output_weights_.emplace(target_id, weight).second;
    }

    bool add_input(size_t source_id, double weight) {
        if(source_id == id_) throw std::invalid_argument("No self-connections allowed");
        return input_weights_.emplace(source_id, weight).second;
    }

    // Dynamic disconnection
    bool disconnect_from(size_t target_id) {
        return output_weights_.erase(target_id) > 0;
    }

    bool remove_input(size_t source_id) {
        return input_weights_.erase(source_id) > 0;
    }

    // STDP implementation with biological explanations
    void update_weights(double current_time, const std::unordered_map<size_t, double>& spiking_inputs) {
        for(auto& [source_id, weight] : input_weights_) {
            if(spiking_inputs.count(source_id)) {
                double delta_t = current_time - spiking_inputs.at(source_id);

                // LTP: pre-before-post spikes (Hebbian learning)
                if(delta_t > 0) {
                    double dw = stdp_learning_rate_ * exp(-delta_t / stdp_tau_plus_);
                    weight = std::min(1.0, weight + dw);
                }
                // LTD: post-before-pre spikes (anti-Hebbian)
                else if(delta_t < 0 && has_spiked_) {
                    double dw = -stdp_learning_rate_ * exp(delta_t / stdp_tau_minus_);
                    weight = std::max(0.0, weight + dw);
                }
            }
        }
    }

    // Neuron state update
    bool step(double dt, double current_time, const std::unordered_map<size_t, double>& spiking_inputs) {
        if(dt <= 0) throw std::invalid_argument("Time step must be positive");

        // Integrate inputs
        double I = 0.0;
        for(const auto& [id, strength] : spiking_inputs) {
            if(input_weights_.count(id)) {
                I += input_weights_.at(id) * strength;
            }
        }

        // Izhikevich equations
        double dv = (0.04*v_*v_ + 5*v_ + 140 - u_ + I) * dt;
        double du = (a_*(b_*v_ - u_)) * dt;

        v_ += dv;
        u_ += du;

        // Spike condition
        has_spiked_ = (v_ >= 30.0);
        if(has_spiked_) {
            last_spike_time_ = current_time;
            v_ = c_;
            u_ += d_;
        }

        // Update plasticity
        update_weights(current_time, spiking_inputs);

        return has_spiked_;
    }
};

/**
 * @brief Example usage demonstrating primitive nervous system simulation
 * 
 * This example shows how to:
 * 1. Create a network with different neuron types
 * 2. Implement dynamic connectivity
 * 3. Simulate with STDP plasticity
 * 4. Handle biological constraints
 */
void run_primitive_nervous_system_simulation() {
    try {
        // Create neurons with biologically realistic parameters
        IzhikevichNeuron sensory_neuron(0, 0.02, 0.2, -65, 8);  // Regular spiking (sensory)
        IzhikevichNeuron interneuron(1, 0.1, 0.2, -65, 2);      // Fast spiking (inhibitory)
        IzhikevichNeuron motor_neuron(2, 0.02, 0.2, -65, 8);    // Regular spiking (motor)

        // Connect neurons - simulating primitive reflex arc
        sensory_neuron.connect_to(interneuron.id_, 0.5);
        sensory_neuron.connect_to(motor_neuron.id_, 0.4);

        // Simulate network
        for(double t = 0; t < 1000; t += 1.0) {
            std::unordered_map<size_t, double> spikes;

            // Sensory input (simulating environmental stimulus)
            if(t > 100 && t < 150) {
                spikes[0] = 1.0;  // Sensory neuron spikes
            }

            // Update neurons
            bool sensory_spike = sensory_neuron.step(1.0, t, spikes);
            bool interneuron_spike = interneuron.step(1.0, t, {{0, sensory_spike ? 1.0 : 0.0}});
            motor_neuron.step(1.0, t, {{0, sensory_spike ? 1.0 : 0.0}, 
                                       {1, interneuron_spike ? -0.5 : 0.0}});

            // Dynamic disconnection example
            if(t == 300) {
                sensory_neuron.disconnect_from(interneuron.id_);
            }
        }
    } catch(const std::exception& e) {
        std::cerr << "Simulation error: " << e.what() << std::endl;
    }
}
```

### Biological Explanations:
1. **Neuron Types**:
   - Regular spiking (sensory/motor neurons) modeled with a=0.02, d=8
   - Fast spiking (inhibitory interneurons) modeled with a=0.1, d=2

2. **STDP Plasticity**:
   - LTP strengthens frequently used pathways (learning)
   - LTD weakens unused connections (synaptic pruning)

3. **Error Handling**:
   - Validates biological parameter ranges
   - Prevents invalid connections
   - Checks time step validity

### Performance Considerations:
1. **Memory**:
   - Uses unordered_maps for sparse connectivity
   - Minimal neuron state storage

2. **Computation**:
   - Efficient STDP implementation
   - Vectorized operations where possible

